CREATE TEMP TABLE lesson_composite_designs (case_id TEXT PRIMARY KEY, query_shape TEXT NOT NULL, key_columns TEXT NOT NULL, include_columns TEXT NOT NULL, predicate_definition TEXT NOT NULL, leading_prefix TEXT NOT NULL, fixture_examples TEXT NOT NULL, authored_outcome TEXT NOT NULL, limitation TEXT NOT NULL);
INSERT INTO pg_temp.lesson_composite_designs VALUES
  ('student-unpaid', 'student_id = 7 AND status = ''open'' ORDER BY due_date', '(student_id, due_date)', '(invoice_id, amount)', 'status = ''open''', 'student_id + due_date', '1001@2026-10-05;1002@2026-10-18', 'strong-candidate', 'partial predicate must be implied by query'),
  ('due-date-only', 'due_date >= DATE ''2026-10-01'' ORDER BY due_date', '(student_id, due_date)', '(invoice_id)', 'none', 'not matched from leading key', '1001@2026-10-05;1003@2026-10-07;1005@2026-10-12;1002@2026-10-18;1004@2026-10-20;1006@2026-11-01', 'full-index-scan-filter-candidate', 'full index scan may be needed; no global due_date order'),
  ('parameterized-status', 'student_id = $1 AND status = $2 ORDER BY due_date', '(student_id, due_date)', '(invoice_id, amount)', 'status = ''open''', 'student_id + due_date', 'student 7 can be 1001,1002,1006; status unknown', 'partial-not-proven', 'unknown parameter may not imply open');

